import pytest

app = FastAPI()

@app.post("/strict")
async def strict_endpoint(item: dict = Body(..., strict_content_type=True)):
    return item

@app.post("/non-strict")
async def non_strict_endpoint(item: dict = Body(..., strict_content_type=False)):
    return item

client = TestClient(app)

def test_strict_json():
    # Exact application/json should work
    response = client.post("/strict", json={"foo": "bar"}, headers={"Content-Type": "application/json"})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

def test_strict_plus_json():
    # application/vnd.api+json should fail
    response = client.post("/strict", json={"foo": "bar"}, headers={"Content-Type": "application/vnd.api+json"})
    assert response.status_code == 415
    assert response.json() == {"detail": "Unsupported Media Type"}

def test_strict_no_content_type():
    # No content type should fail
    response = client.post("/strict", json={"foo": "bar"}, headers={})
    assert response.status_code == 415
    assert response.json() == {"detail": "Unsupported Media Type"}

def test_strict_wrong_content_type():
    # Wrong content type should fail
    response = client.post("/strict", json={"foo": "bar"}, headers={"Content-Type": "text/plain"})
    assert response.status_code == 415
    assert response.json() == {"detail": "Unsupported Media Type"}

def test_non_strict_plus_json():
