def test_non_strict_no_content_type():
    # No content type should work
    response = client.post("/non-strict", json={"foo": "bar"}, headers={})
    assert response.status_code == 200
    assert response.json() == {"foo": "bar"}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
